474   * Make all variable names lowercase;
475   options mprint;
476   %macro lowcase(dsn);
477        %let dsid=%sysfunc(open(&dsn));
478        %let num=%sysfunc(attrn(&dsid,nvars));
479        %put &num;
480        data &dsn;
481              set &dsn(rename=(
482           %do i = 1 %to &num;
483           %let var&i=%sysfunc(varname(&dsid,&i));      /*function of varname returns the
              name of a SAS data set variable*/
484           &&var&i=%sysfunc(lowcase(&&var&i))         /*rename all variables*/
485           %end;));
486           %let close=%sysfunc(close(&dsid));
487     run;
488   %mend lowcase;
489
490   %lowcase(master)
491
492   data homed.master;
493       set master;
494   run;
